                R(ref s, "But...<E003 4><E145 18 13><E204 140 10 0><E003 12><E335><E025 1>but that makes no sense!", "Mais...<E003 4><E145 18 13><E204 140 10 0><E003 12><E335><E025 1>mais cela n'a aucun sens !");
                R(ref s, "Why on earth wouldn't Klint have entrusted the child to\r\nmy care in that case?!", "Pourquoi diable Klint n'aurait-il pas confié cet enfant à mes\nsoins dans ce cas ?!");
                R(ref s, "I was completely unaware that he even had a daughter!", "J'ignorais totalement qu'il avait une fille !");
                R(ref s, "I suppose...<E003 16><E330>he didn't really have any choice.", "J'imagine...<E003 16><E330>qu'il n'avait guère le choix.");
                R(ref s, "What?", "Quoi ?");
                R(ref s, "Well, <E003 8>your brother said that he'd <E006>confessed<E005> everything to\r\nhis wife.", "Eh bien, <E003 8>votre frère disait avoir tout <E006>avoué<E005> à son\népouse.");
                R(ref s, "So she must have been beside herself with worry for her\r\nchild.", "Elle devait donc être rongée d'angoisse pour son enfant.");
                R(ref s, "If <E006>the true identity<E005> of the Professor were ever to be made\r\npublic...", "Si jamais <E006>la véritable identité<E005> du Professeur venait à être\nrendue publique...");
                R(ref s, "...the girl would be forever branded as the daughter of the\r\ninfamous mass murderer.", "... la fillette porterait à vie le stigmate d'être la fille de cet\ninfâme boucher.");
                R(ref s, "Ah!", "Ah !");
                R(ref s, "So the only solution...", "La seule solution...");
                R(ref s, "...was to distance the young girl from the van Zieks family\r\nas much as possible.", "... était donc d'éloigner cette fillette de la famille Van Peers\nle plus possible.");
                R(ref s, "I...<E003 12><E025 3>don't believe it...", "Je...<E003 12><E025 3>n'arrive pas à y croire...");
                R(ref s, "I imagine that in his final hour, <E049><E003 10><E025 3>Lord Klint van Zieks made\r\nthe obvious choice.", "J'imagine qu'à sa dernière heure, <E049><E003 10><E025 3>Lord Klint Van Peers a fait\nle choix qui s'imposait.");
                R(ref s, "He would have thought to himself, <E049><E003 10><E025 3><E239>‘This Japanese man\r\nhere is someone I can <E006>trust<E005>...’", "Il a dû se dire : <E049><E003 10><E025 3><E239>« Cet homme japonais est digne de toute ma\n<E006>confiance<E005>... »");
                R(ref s, "I honoured my promise to Genshin, <E049><E003 8>of course.", "J'ai bien entendu tenu ma promesse envers Genshin.");
                R(ref s, "However...", "Toutefois...");
                R(ref s, "...only a month later, <E049><E003 10><E025 3>I was summoned back to Japan.", "... un mois plus tard seulement, <E049><E003 10><E025 3>j'ai été rappelé au Japon.");
                R(ref s, "And without disclosing the parentage of the child,<E049><E003 8><E025 3><E136 46 67 5><E117 46 20><E003 7><E239> I\r\ncouldn't obtain permission to take her with me.", "Et sans révéler la lignée de l'enfant,<E049><E003 8><E025 3><E136 46 67 5><E117 46 20><E003 7><E239> je ne\npouvais obtenir l'autorisation de l'emmener.");
                R(ref s, "Oh <E049><E003 8>how awful...", "Oh, <E049><E003 8>quelle douleur...");
                R(ref s, "I was completely at a loss.<E049><E003 14>\r\n<E025 2>In the end, <E049><E003 10><E025 3>I had to ask my <E006>great friend<E005>.", "J'étais dans une impasse absolue.<E049><E003 14>\n<E025 2>Au final, <E049><E003 10><E025 3>j'ai dû m'adresser à mon <E006>grand ami<E005>.");
                R(ref s, "I asked him if he would be a father to her.", "Je lui ai demandé s'il accepterait de lui servir de père.");
                R(ref s, "That...<E003 14><E025 2><E333><E342>being Mr Sholmes, <E003 12><E025 2><E341>I presume?", "C'est-à-dire...<E003 14><E025 2><E333><E342>M. Sholmes, <E003 12><E025 2><E341>je présume ?");
                R(ref s, "Yes.", "Oui.");
                R(ref s, "He took one look into my eyes and agreed to it on the\r\nspot.", "Il a lu dans mes yeux et a accepté sur-le-champ.");
                R(ref s, "(Mr Sholmes...<E003 12> He has a heart of gold...)", "(M. Sholmes...<E003 12> Il a le cœur sur la main...)");
                R(ref s, "Really, <E049><E003 15>all it can be said that I did for the child...", "En vérité, <E049><E003 15>tout ce que j'ai fait pour elle...");
                R(ref s, "...was to give her a name.", "... ce fut de lui donner un prénom.");
                R(ref s, "Oh?", "Vraiment ?");
                R(ref s, "When I'd come to Britain, <E049><E003 8><E025 3>I was trying to escape from the\r\ngrief of losing my darling wife.", "Quand je suis venu en Angleterre, <E049><E003 8><E025 3>je cherchais à échapper au deuil\nde ma bien-aimée disparue.");
                R(ref s, "So it was her name that I gave the little girl.", "C'est donc son prénom que j'ai transmis à l'enfant.");
                R(ref s, "Your wife's name, <E003 8>Professor Mikotoba...<E003 14>\r\n<E025 3><E341>In other words...", "Le prénom de votre épouse, <E003 8>professeur Mikotoba...<E003 14>\n<E025 3><E341>Autrement dit...");
                R(ref s, "...The name of my mother...", "... Le prénom de ma mère...");
                R(ref s, "Ayame Mikotoba<E049><E003 8><E025 7>...<E003 2>...<E003 4>...", "Ayame Mikotoba<E049><E003 8><E025 7>...<E003 2>...<E003 4>...");
                R(ref s, "Oh!", "Oh !");
                R(ref s, "That's right, <E049><E003 8>Ayame.<E049><E003 15><E145 46 64><E149 46 0 0><E117 46 20><E003 15>\r\n<E025 2>Or in English...<E049><E003 14><E239><E092 6><E025 3><E006>Iris<E005>.", "C'est exact, <E049><E003 8>Ayame.<E049><E003 15><E145 46 64><E149 46 0 0><E117 46 20><E003 15>\r\n<E025 2>Ou en français...<E049><E003 14><E239><E092 6><E025 3><E006>Iris<E005>.");
                R(ref s, "Iris...", "Iris...");
                R(ref s, "I, <E049><E003 10>I had no idea...", "Je, <E049><E003 10>je n'en avais aucune idée...");
                return s;
            };

